def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['carrying_target'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['carrying_target'] = False
    if verb and target and act.startswith(verb + ' ') and target in act and 'you ' + verb in obs:
        nb['transformed'] = True
    pc = val(ctx, 'world.placed_count', None)
    if isinstance(pc, int) and pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    if target and act.startswith('put ') and target in act and 'you put' in obs and dest and dest in act:
        nb['placed_count'] = nb.get('placed_count', 0) + 1
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    take_ok = bool(target and any(a.startswith('take ') and target in a for a in ctx.get('admissible', [])))
    put_ok = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in ctx.get('admissible', [])))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and put_ok:
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif take_ok:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

