def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place a substitute; recover by setting it aside if needed and searching for the exact target.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target type instead of other objects.'
    elif stage == 'transform' and target and verb:
        msg = 'You are carrying the target but must ' + verb + ' it before placing. Use the matching appliance or action, then carry it to the destination.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and put it there; do not place it on a different receptacle.'
    elif stage == 'put_target' and target and dest:
        msg = 'The destination put is available now. Put the ' + target + ' in/on the ' + dest + ' and do not take it back.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

