def hook(ctx, nb):
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    verb = nb.get('required_verb') or needverb(tt)
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if not act or not target:
        return None
    if verb and not nb.get('transformed') and act.startswith('put ') and target in act and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. This task requires ' + verb + 'ing the target first; carry it to the proper appliance or use the matching transform action.'}
    if act.startswith('put ') and target in act and dest and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Carry the target to a ' + dest + ' instead of placing it elsewhere.'}
    if act.startswith('take ') and target in act and dest and dest in act and nb.get('placed_count', 0) > 0 and (not verb or nb.get('transformed')):
        return {'kind': 'block_and_prompt', 'message': 'Do not take back an item that has already been placed at the destination. Continue only if another required target is still missing.'}
    return None
